package br.com.marealta.db;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import java.sql.Connection;
import java.sql.SQLException;
import java.sql.Statement;

/** Connection pool, schema creation and transaction helper. */
public final class Database implements AutoCloseable {

    @FunctionalInterface
    public interface Work<T> {
        T run(Connection connection) throws SQLException;
    }

    private static final String SCHEMA = """
            CREATE TABLE IF NOT EXISTS rooms (
                number       INTEGER PRIMARY KEY,
                type         VARCHAR(20) NOT NULL,
                capacity     INTEGER NOT NULL,
                nightly_rate NUMERIC(12,2) NOT NULL
            );
            CREATE TABLE IF NOT EXISTS reservations (
                id          BIGSERIAL PRIMARY KEY,
                room_number INTEGER NOT NULL REFERENCES rooms(number),
                guest_name  TEXT NOT NULL,
                guest_email TEXT NOT NULL,
                guest_cpf   TEXT NOT NULL,
                check_in    DATE NOT NULL,
                check_out   DATE NOT NULL,
                guests      INTEGER NOT NULL,
                rate_plan   VARCHAR(20) NOT NULL,
                nights      INTEGER NOT NULL,
                subtotal    NUMERIC(12,2) NOT NULL,
                discount    NUMERIC(12,2) NOT NULL,
                total       NUMERIC(12,2) NOT NULL,
                status      VARCHAR(20) NOT NULL,
                amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0,
                refund      NUMERIC(12,2)
            );
            CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in);
            CREATE INDEX IF NOT EXISTS reservations_check_in_idx ON reservations (check_in);
            CREATE TABLE IF NOT EXISTS messages (
                id      BIGSERIAL PRIMARY KEY,
                channel VARCHAR(20) NOT NULL,
                to_addr TEXT NOT NULL,
                subject TEXT NOT NULL,
                body    TEXT NOT NULL
            );
            INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
                (101, 'STANDARD', 2, 249.90),
                (102, 'STANDARD', 2, 249.90),
                (201, 'DELUXE',   3, 389.90),
                (202, 'DELUXE',   3, 389.90),
                (301, 'SUITE',    4, 579.90)
            ON CONFLICT (number) DO NOTHING;
            """;

    private final HikariDataSource pool;

    public Database(String url, String user, String password) {
        HikariConfig cfg = new HikariConfig();
        cfg.setJdbcUrl(url);
        if (user != null) cfg.setUsername(user);
        if (password != null) cfg.setPassword(password);
        cfg.setMaximumPoolSize(10);
        cfg.setInitializationFailTimeout(-1); // the database may still be starting up
        this.pool = new HikariDataSource(cfg);
    }

    /** Creates what the system needs, waiting for the database to accept connections. */
    public void migrate() {
        long deadline = System.currentTimeMillis() + 60_000;
        while (true) {
            try {
                transaction(c -> {
                    try (Statement st = c.createStatement()) {
                        // serializes concurrent starts of several instances
                        st.execute("SELECT pg_advisory_xact_lock(727274)");
                        st.execute(SCHEMA);
                    }
                    return null;
                });
                return;
            } catch (RuntimeException e) {
                if (System.currentTimeMillis() > deadline) throw e;
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    throw e;
                }
            }
        }
    }

    public <T> T transaction(Work<T> work) {
        try (Connection c = pool.getConnection()) {
            c.setAutoCommit(false);
            try {
                T result = work.run(c);
                c.commit();
                return result;
            } catch (Throwable t) {
                c.rollback();
                throw t;
            }
        } catch (SQLException e) {
            throw new IllegalStateException("Database error: " + e.getMessage(), e);
        }
    }

    @Override
    public void close() {
        pool.close();
    }
}
EOF
