        Res rev = call("GET", "/reports/revenue?month=2027-08", null);
        assertTrue(rev.body().contains(",CANCELLED,986.82\n"), rev.body());
        assertEquals(404, call("GET", "/reservations/abc", null).status());
        assertEquals(Map.of(), Map.of());
    }
}
